"""Русский язык, 3 класс."""
from rus_common import *


def t_speech(r):
    t = []
    t.append(ch("Какие бывают виды речи?", "устная и письменная", ["громкая и тихая", "короткая и длинная"], "Речь бывает устная и письменная; также есть внутренняя речь.", "Слышим или читаем?"))
    t.append(ch("Как называется речь, когда человек думает про себя?", "внутренняя", ["устная", "письменная"], "Внутренняя речь — мысленная.", "Про себя."))
    t.append(ch("Какая форма речи — разговор двух собеседников?", "диалог", ["монолог", "текст-описание"], "Диалог — форма речи двух и более собеседников.", "«Ди» — два."))
    t.append(ch("Выступление ученика с докладом — это…", "монолог", ["диалог", "реплика"], "Говорит один человек — монолог.", "Сколько говорящих?"))
    t.append(sort_("Разложи по видам речи.", [("Устная", ["рассказ по телефону", "ответ на уроке"]), ("Письменная", ["сочинение", "открытка"]), ("Внутренняя", ["обдумывание ответа"])], "Устная звучит, письменная записана, внутренняя — в мыслях.", "Где звучит речь?"))
    t.append(multi("Какой должна быть хорошая речь?", ["понятной", "вежливой", "правильной"], ["грубой", "очень быстрой и невнятной"], "Хорошая речь понятная, правильная, вежливая.", "Как приятно слушать?"))
    t.append(tf("По речи можно узнать, вежлив ли человек.", True, "Речь показывает воспитание и культуру.", "Слова выдают характер."))
    t.append(fill("Речь, которую мы пишем и читаем, называется ___.", "письменной", ["устной", "внутренней"], "Письменная речь.", "На бумаге."))
    t.append(match("Соедини слово и значение.", [("монолог", "речь одного человека"), ("диалог", "разговор двоих и более"), ("реплика", "слова одного участника диалога")], "Формы речи.", "Моно — один."))
    t.append(fix("Найди ошибку: «Сочинение — это устная речь».", ["Сочинение", "—", "устная", "речь"], 2, "письменная", ["внутренняя", "громкая"], "Сочинение пишут — это письменная речь.", "Сочинение пишут."))
    return t


def t_text_types(r):
    t = []
    for txt, a in [("Белка — красивый зверёк. У неё рыжая шубка, пушистый хвост и кисточки на ушах.", "описание"),
                   ("Утром мы пошли в лес. Сначала собирали грибы, потом развели костёр, а вечером вернулись домой.", "повествование"),
                   ("Зимой нужно подкармливать птиц, потому что им трудно найти корм под снегом.", "рассуждение"),
                   ("Почему осенью листья желтеют? Потому что становится холоднее и света меньше, и в листьях разрушается зелёное вещество.", "рассуждение"),
                   ("Жил-был ёжик. Однажды он нашёл яблоко, принёс его домой и угостил друзей.", "повествование")]:
        t.append(ch("Определи тип текста.", a, [x for x in ["описание", "повествование", "рассуждение"] if x != a], {"описание": "Текст описывает, какой предмет (вопрос «какой?»).", "повествование": "Текст рассказывает о событиях по порядку (что произошло?).", "рассуждение": "Текст объясняет причину (почему?)."}[a], "Какой вопрос можно задать к тексту?", text=txt))
    t.append(match("Соедини тип текста и вопрос к нему.", [("описание", "какой?"), ("повествование", "что произошло?"), ("рассуждение", "почему?")], "Тип текста определяют по вопросу.", "Вспомни вопросы."))
    t.append(order("Расставь части рассуждения.", ["Утверждение: собака — друг человека.", "Доказательство: она охраняет дом и помогает людям.", "Вывод: поэтому собаку любят."], "Рассуждение: тезис, доказательство, вывод.", "С чего начинают?"))
    t.append(tf("В тексте-повествовании события идут друг за другом.", True, "Повествование рассказывает о событиях по порядку.", "Сначала, потом, наконец."))
    t.append(multi("Какие слова часто встречаются в рассуждении?", ["потому что", "поэтому", "так как"], ["однажды", "жил-был"], "Слова-связки причины.", "Объяснение."))
    t.append(fix("Найди ошибку: «Текст, отвечающий на вопрос „почему?“, — это описание».", ["почему?", "—", "описание"], 2, "рассуждение", ["повествование", "заголовок"], "На вопрос «почему?» отвечает рассуждение.", "Объяснение причины."))
    return t


def t_sent_purpose(r):
    t = []
    for s, a in [("Как называется эта птица?", "вопросительное"), ("Закрой, пожалуйста, окно.", "побудительное"), ("Наступила весна.", "повествовательное"), ("Давай пойдём в парк!", "побудительное"), ("Ты любишь читать?", "вопросительное"), ("Солнце садится за лес.", "повествовательное")]:
        t.append(ch(f"Определи вид предложения по цели высказывания: «{s}»", a, [x for x in ["повествовательное", "вопросительное", "побудительное"] if x != a], {"повествовательное": "В предложении о чём-то сообщается.", "вопросительное": "В предложении задаётся вопрос.", "побудительное": "Предложение побуждает к действию: просьба, совет, приказ."}[a], "Сообщает, спрашивает или просит?"))
    for s, a in [("Как красиво вокруг!", "восклицательное"), ("Сегодня дождь.", "невосклицательное")]:
        t.append(ch(f"По интонации предложение «{s}» —", a, ["невосклицательное" if a == "восклицательное" else "восклицательное"], "Восклицательное произносится с сильным чувством, в конце «!».", "Есть ли сильное чувство?"))
    t.append(sort_("Разложи предложения.", [("Вопросительные", ["Где ты был?", "Который час?"]), ("Побудительные", ["Помоги мне.", "Пойдём гулять!"]), ("Повествовательные", ["Идёт снег.", "Я люблю книги."])], "Цель высказывания: сообщить, спросить, побудить.", "Что хочет говорящий?"))
    t.append(tf("Побудительное предложение может быть восклицательным.", True, "Например: «Вперёд!»", "Может ли просьба быть с сильным чувством?"))
    return t


def t_address(r):
    t = []
    for s, a in [("Мама, посмотри на радугу!", "Мама"), ("Ребята, идите обедать.", "Ребята"), ("Скажи, Петя, который час?", "Петя"), ("Здравствуй, лес!", "лес")]:
        t.append(ch(f"Найди обращение: «{s}»", a, [w.strip(",.!?") for w in s.split() if w.strip(",.!?") != a][:3], f"Обращение — слово, называющее того, к кому обращаются: «{a}».", "К кому обращаются?"))
    t.append(ch("Как выделяется обращение на письме?", "запятыми", ["кавычками", "скобками"], "Обращение выделяется запятыми (или восклицательным знаком).", "Знаки препинания."))
    t.append(tf("Обращение является членом предложения.", False, "Обращение не является членом предложения.", "Подчёркивается ли обращение?"))
    t.append(fill("Поставь знак: «Друзья___ давайте играть!»", ",", ["!", "—"], "Обращение отделяется запятой.", "После обращения."))
    t.append(fix("Найди ошибку: «Бабушка я пришёл!»", ["Бабушка", "я", "пришёл!"], 0, "Бабушка,", ["Бабушка.", "Бабушка?"], "Обращение отделяется запятой: «Бабушка, я пришёл!»", "Где запятая?"))
    t.append(multi("В каких предложениях есть обращение?", ["Коля, иди сюда.", "Солнышко, выгляни!"], ["Коля идёт сюда.", "Солнышко выглянуло."], "Обращение — к кому обращаются.", "Обращаются к кому-то?"))
    t.append(build("Составь предложение с обращением: «Аня, помоги, пожалуйста».", ["Аня,", "помоги,", "пожалуйста."], ["Аня"], "Аня, помоги, пожалуйста.", "Обращение в начале."))
    return t


def t_members(r):
    t = []
    t.append(ch("Какие члены предложения главные?", "подлежащее и сказуемое", ["определение и дополнение", "обстоятельство"], "Главные члены — подлежащее и сказуемое.", "Основа."))
    t.append(ch("Какие члены предложения второстепенные?", "определение, дополнение, обстоятельство", ["подлежащее и сказуемое", "обращение"], "Второстепенные поясняют главные.", "Не основа."))
    for s, w, role in [("Высокая сосна растёт на опушке.", "высокая", "второстепенный"), ("Высокая сосна растёт на опушке.", "сосна", "главный"), ("Мы читаем интересную книгу.", "книгу", "второстепенный"), ("Мы читаем интересную книгу.", "читаем", "главный")]:
        t.append(ch(f"Каким членом является слово «{w}» в предложении «{s}»?", role, ["главный" if role == "второстепенный" else "второстепенный"], "Главные: подлежащее и сказуемое; остальные — второстепенные.", "Входит ли слово в основу?"))
    t.append(multi("Найди грамматическую основу: «Весёлые ребята катаются на санках».", ["ребята", "катаются"], ["весёлые", "на санках"], "Кто? — ребята; что делают? — катаются.", "Кто и что делает?"))
    t.append(sort_("Разложи члены предложения «Маленький щенок громко лает».", [("Главные", ["щенок", "лает"]), ("Второстепенные", ["маленький", "громко"])], "Основа: щенок лает.", "Найди основу."))
    t.append(tf("Предложение может состоять только из главных членов.", True, "Например: «Светает»; «Дети играют».", "Нераспространённое предложение."))
    t.append(fix("Найди ошибку: «В предложении „Птицы поют“ сказуемое — птицы».", ["сказуемое", "—", "птицы"], 2, "поют", ["подлежащее", "песни"], "Поют — сказуемое.", "Что делают?"))
    return t


def t_simple_complex(r):
    t = []
    for s, a in [("Наступила осень, и птицы улетели на юг.", "сложное"), ("Птицы улетели на юг.", "простое"), ("Светит солнце, тает снег.", "сложное"), ("Дети катались на коньках и лыжах.", "простое"), ("Прозвенел звонок, и урок начался.", "сложное")]:
        t.append(ch(f"Простое или сложное предложение: «{s}»", a, ["сложное" if a == "простое" else "простое"], "В сложном предложении две и более грамматические основы.", "Сколько основ?"))
    t.append(ch("Сколько грамматических основ в сложном предложении?", "две и более", ["одна", "ни одной"], "Сложное — из двух и более простых.", "Больше одной."))
    t.append(fill("Части сложного предложения на письме обычно разделяются ___.", "запятой", ["тире в начале", "кавычками"], "Между частями сложного предложения ставится запятая.", "Знак препинания."))
    t.append(build("Составь сложное предложение из двух: «Пошёл дождь. Мы вернулись домой».", ["Пошёл", "дождь,", "и", "мы", "вернулись", "домой."], ["но"], "Пошёл дождь, и мы вернулись домой.", "Соедини союзом «и»."))
    t.append(multi("Выбери сложные предложения.", ["Ветер стих, и выглянуло солнце.", "Я читаю, а брат рисует."], ["Ветер стих.", "Мы пели и танцевали."], "В сложных — две основы.", "Найди основы."))
    t.append(fix("Найди ошибку: «Зазвенел звонок и дети побежали в класс».", ["звонок", "и", "дети"], 0, "звонок,", ["звонок.", "звонок!"], "Перед «и», соединяющим части сложного предложения, ставится запятая.", "Две основы."))
    return t


def t_phrase(r):
    t = []
    for p, main, q in [("лесная тропинка", "тропинка", "какая?"), ("читать книгу", "читать", "что?"), ("бежать быстро", "бежать", "как?"), ("домик у реки", "домик", "где?")]:
        t.append(ch(f"Какое слово главное в словосочетании «{p}»?", main, [w for w in p.split() if w != main and len(w) > 2], f"От главного слова задаём вопрос: {main} ({q}).", "От какого слова задаём вопрос?"))
    t.append(ch("Что такое словосочетание?", "два слова, связанных по смыслу, одно из которых главное", ["подлежащее со сказуемым", "одно слово"], "В словосочетании есть главное и зависимое слово.", "Главное и зависимое."))
    t.append(tf("Подлежащее и сказуемое образуют словосочетание.", False, "Грамматическая основа — не словосочетание.", "Основа или пара слов?"))
    t.append(multi("Выбери словосочетания из предложения «Яркое солнце осветило поляну».", ["яркое солнце", "осветило поляну"], ["солнце осветило", "яркое поляну"], "«Солнце осветило» — основа, а не словосочетание.", "Не бери основу."))
    t.append(match("Составь словосочетания.", [("спелое", "яблоко"), ("пить", "сок"), ("идти", "медленно")], "Слова связаны по смыслу.", "Подбери по смыслу."))
    t.append(fill("В словосочетании «зелёный луг» вопрос задаём от слова ___.", "луг", ["зелёный", "какой"], "Луг (какой?) зелёный.", "Главное слово."))
    t.append(fix("Найди ошибку: «В словосочетании „ловить рыбу“ главное слово — рыбу».", ["главное", "слово", "рыбу"], 2, "ловить", ["рыба", "ловля"], "Ловить (что?) рыбу.", "От чего вопрос?"))
    return t


def t_polysemy(r):
    t = []
    for w, ms in [("ключ", ["от двери", "родник"]), ("лисичка", ["зверёк", "гриб"]), ("ручка", ["для письма", "у двери"]), ("нос", ["у человека", "у корабля"])]:
        t.append(tf(f"Слово «{w}» многозначное: {ms[0]} и {ms[1]}.", True, f"У слова «{w}» несколько связанных значений.", "Сколько значений у слова?"))
    t.append(ch("Какое слово однозначное?", "берёза", ["ключ", "иголка", "хвост"], "«Берёза» имеет одно значение — дерево.", "У какого слова одно значение?"))
    t.append(ch("Что такое многозначное слово?", "слово, у которого несколько значений", ["слово из многих букв", "слово, которое пишется по-разному"], "Многозначное — несколько значений.", "Много значений."))
    t.append(sort_("Разложи слова.", [("Однозначные", ["трамвай", "тюльпан"]), ("Многозначные", ["иголка", "крыло"])], "Многозначные имеют несколько значений: иголка ели и швейная.", "Сколько значений?"))
    t.append(match("Соедини значение слова «иголка».", [("для шитья", "швейная иголка"), ("у ёлки", "хвойная иголка"), ("у ежа", "колючка")], "Слово «иголка» многозначное.", "Где бывают иголки?"))
    t.append(fill("Где узнать все значения слова? В ___ словаре.", "толковом", ["орфографическом", "английском"], "Толковый словарь объясняет значения.", "Толкует слова."))
    t.append(multi("Какие слова многозначные?", ["язык", "ножка"], ["мармелад", "жираф"], "Язык (во рту и речь), ножка (стола, гриба).", "Есть ли разные значения?"))
    return t


def t_figurative(r):
    t = []
    for p, a in [("золотое кольцо", "прямое"), ("золотые руки", "переносное"), ("горячий чай", "прямое"), ("горячее сердце", "переносное"), ("идёт дождь", "переносное"), ("идёт человек", "прямое")]:
        t.append(ch(f"В каком значении употреблено слово в сочетании «{p}»?", a, ["переносное" if a == "прямое" else "прямое"], "Переносное значение — перенесено с одного предмета на другой по сходству." if a == "переносное" else "Прямое значение — основное значение слова.", "Буквально или образно?"))
    t.append(sort_("Разложи сочетания.", [("Прямое значение", ["острый нож", "тихий голос"]), ("Переносное значение", ["острый ум", "тихая река"])], "Переносное значение образное.", "Буквально ли?"))
    t.append(tf("В выражении «лес дремлет» слово «дремлет» в переносном значении.", True, "Лес не спит по-настоящему — это образ.", "Может ли лес спать?"))
    t.append(match("Подбери пары.", [("каменный дом", "прямое"), ("каменное сердце", "переносное"), ("железный гвоздь", "прямое ")][:2] + [("железный характер", "переносное ")], "Переносное — образное.", "Буквально или образно?") if False else
             ch("Где слово «волна» в переносном значении?", "волна радости", ["морская волна", "высокая волна"], "Радость не вода — значение переносное.", "Образно."))
    t.append(fix("Найди ошибку: «В „светлая голова“ слово „светлая“ в прямом значении».", ["светлая", "в", "прямом", "значении"], 2, "переносном", ["обратном", "главном"], "«Светлая голова» — умный человек: переносное значение.", "Голова светится?"))
    return t


def t_syn_ant(r):
    t = []
    syn = [("мокрый", "влажный"), ("ярко", "светло"), ("метель", "вьюга"), ("работа", "труд"), ("смотреть", "глядеть")]
    ant = [("мокрый", "сухой"), ("тяжёлый", "лёгкий"), ("широкий", "узкий"), ("правда", "ложь"), ("рано", "поздно")]
    for a, b in r.sample(syn, 3):
        t.append(ch(f"Синоним к слову «{a}»:", b, [x for _, x in ant][:2] + [r.choice([x for _, x in syn if x != b])], f"«{a}» — «{b}»: близки по значению.", "Близко по смыслу."))
    for a, b in r.sample(ant, 3):
        t.append(ch(f"Антоним к слову «{a}»:", b, [r.choice([x for _, x in syn])] + [x for _, x in ant if x != b][:2], f"«{a}» — «{b}»: противоположны.", "Противоположное."))
    t.append(sort_("Разложи пары.", [("Синонимы", ["храбрый — смелый", "бежать — мчаться"]), ("Антонимы", ["зима — лето", "добрый — злой"])], "Синонимы близки, антонимы противоположны.", "Похожи или противоположны?"))
    t.append(fill("Пословица: «Не красна изба углами, а красна ___».", "пирогами", ["окнами", "стенами"], "Пословица учит: главное — гостеприимство.", "Чем угощают гостей?"))
    t.append(multi("Выбери антонимы к слову «добрый».", ["злой", "жестокий"], ["хороший", "ласковый"], "Злой и жестокий — противоположны доброму.", "Противоположность."))
