def t_verb_number(r):
    t = []
    for one, many in [("растёт", "растут"), ("кричит", "кричат"), ("моет", "моют"), ("ждёт", "ждут"), ("спал", "спали")]:
        t.append(ch(f"Множественное число глагола «{one}»:", many, [one + "т", one[:-1]], f"{one} — {many}.", "Что делают?"))
    t.append(sort_("Разложи глаголы по числам.", [("Ед. ч.", ["шумит", "прыгал"]), ("Мн. ч.", ["шумят", "прыгали"])], "Что делает? — ед., что делают? — мн.", "Вопрос."))
    t.append(tf("Глаголы изменяются по числам.", True, "Бежит — бегут.", "Один или много."))
    t.append(fill("Ласточки ___ на юг (улетать).", "улетают", ["улетает", "улетать"], "Ласточки (что делают?) улетают.", "Много ласточек."))
    t.append(fix("Найди ошибку: «Ребята строит снеговика».", ["Ребята", "строит", "снеговика"], 1, "строят", ["строил", "строить"], "Ребята (что делают?) строят.", "Ребята — много."))
    t.append(match("Соедини.", [("солнце", "светит"), ("звёзды", "светят"), ("ручей", "журчит"), ("ручьи", "журчат")], "Число глагола как у подлежащего.", "Один или много?"))
    return t


def t_verb_tense(r):
    t = []
    for w, a in [("читал", "прошедшее"), ("читаю", "настоящее"), ("прочитаю", "будущее"), ("бегу", "настоящее"), ("побежит", "будущее"), ("пел", "прошедшее"), ("будем рисовать", "будущее")]:
        t.append(ch(f"Определи время глагола «{w}».", a, [x for x in ["настоящее", "прошедшее", "будущее"] if x != a], {"прошедшее": "Что делал? — прошедшее время.", "настоящее": "Что делаю? — настоящее время.", "будущее": "Что сделаю? что буду делать? — будущее время."}[a], "Когда происходит действие?"))
    t.append(match("Соедини время и вопрос.", [("настоящее", "что делает?"), ("прошедшее", "что делал?"), ("будущее", "что будет делать?")], "Вопросы времён.", "Сейчас, раньше, потом."))
    t.append(sort_("Разложи глаголы по временам.", [("Прошедшее", ["рисовал", "гулял"]), ("Настоящее", ["рисует", "гуляет"]), ("Будущее", ["нарисует", "погуляет"])], "Времена глагола.", "Когда?"))
    t.append(fix("Найди ошибку: «Вчера я пойду в кино».", ["Вчера", "я", "пойду", "в", "кино"], 2, "ходил", ["иду", "пойдём"], "«Вчера» — прошедшее время: ходил.", "Вчера — было."))
    return t


def t_verb_past_gender(r):
    t = []
    for subj, a, d in [("Мальчик", "читал", ["читала", "читало"]), ("Девочка", "читала", ["читал", "читало"]), ("Солнце", "светило", ["светил", "светила"]), ("Дети", "читали", ["читал", "читала"])]:
        t.append(fill(f"{subj} ___ (прошедшее время).", a, d, "В прошедшем времени глагол в ед. ч. изменяется по родам: -л (м. р.), -ла (ж. р.), -ло (ср. р.).", "Он, она, оно?"))
    t.append(match("Соедини окончание и род.", [("-ла", "женский"), ("-ло", "средний"), ("-л (нулевое)", "мужской"), ("-ли", "мн. число")], "Окончания глаголов прошедшего времени.", "Она пела, оно пело, он пел."))
    t.append(tf("Глаголы настоящего времени изменяются по родам.", False, "По родам изменяются только глаголы прошедшего времени в ед. ч.", "Можно ли сказать «она поёта»?"))
    t.append(sort_("Разложи глаголы по родам.", [("Мужской", ["сказал", "принёс"]), ("Женский", ["сказала", "принесла"]), ("Средний", ["сказало", "принесло"])], "Род по окончанию.", "Он, она, оно."))
    t.append(fix("Найди ошибку: «Ветер дула всю ночь».", ["Ветер", "дула", "всю", "ночь"], 1, "дул", ["дуло", "дули"], "Ветер — м. р.: дул.", "Ветер — он."))
    t.append(fill("Озеро ___ (заблестеть).", "заблестело", ["заблестел", "заблестела"], "Озеро — оно: заблестело.", "Средний род."))
    return t


def t_ne_verb(r):
    t = []
    for w, wr in [("не пришёл", "непришёл"), ("не ленись", "неленись"), ("не мог", "немог"), ("не умеет", "неумеет")]:
        t.append(ch("Как правильно?", w, [wr], "Не с глаголами пишется раздельно.", "Раздельно."))
    t.append(ch("Какое слово пишется с «не» слитно?", "ненавидеть", ["не любить", "не видеть"], "Без «не» глагол «ненавидеть» не употребляется — пишем слитно.", "Есть ли слово «навидеть»?"))
    t.append(multi("Выбери слова, которые без «не» не употребляются.", ["негодовать", "нездоровиться"], ["не сидеть", "не бегать"], "Негодовать, нездоровиться — слитно.", "Попробуй убрать «не»."))
    t.append(fix("Найди ошибку: «Не шуми, малыш нехочет просыпаться».", ["Не", "шуми,", "малыш", "нехочет", "просыпаться"], 3, "не хочет", ["нехочит", "не-хочет"], "Не с глаголом — раздельно.", "Раздельно."))
    t.append(tf("В предложении «Я не знал ответа» «не» пишется раздельно.", True, "Не с глаголом — раздельно.", "Правило."))
    t.append(fill("Дождь ___ прекращался весь день.", "не", ["ни", "нет"], "Частица «не» с глаголом пишется отдельно.", "Отрицание."))
    t.append(build("Составь совет: «не, обижай, младших».", ["Не", "обижай", "младших."], [], "Не обижай младших.", "Начни с «Не»."))
    return t
